import collections
# Create alternate transform: lines internal criteria: cols exclude boundary, then change 2 objects touched by line
code='''def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    from collections import Counter, deque
    rc=Counter(r for r,c in pts); cc=Counter(c for r,c in pts)
    lines=set()
    for r,n in rc.items():
        if n>=2: lines.update((r,c) for c in range(w))
    for c,n in cc.items():
        if n>=2 and c not in (0,w-1): lines.update((r,c) for r in range(h))
    for r,c in lines: out[r][c]=1
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          a,b=q.pop(); comp.append((a,b))
          for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
            if 0<=x<h and 0<=y<w and grid[x][y]==2 and (x,y) not in seen: seen.add((x,y)); q.append((x,y))
        if any((a+dr,b+dc) in lines for a,b in comp for dr,dc in ((0,0),(-1,0),(1,0),(0,-1),(0,1))):
          for a,b in comp: out[a][b]=1
    return out
'''
